#include "migration_status_model.hpp"
#include <QJsonDocument>
#include <QSet>
#include <stdexcept>
namespace migrationStatus {
static void require(bool b,const char* text){if(!b)throw std::runtime_error(text);}
QByteArray bytes(const QJsonObject& o){auto b=QJsonDocument(o).toJson(QJsonDocument::Indented);require(b.size()<=25*1024*1024,"迁移快照超过25MiB；未截断");return b;}
QJsonObject validate(const QJsonObject& o){bytes(o);require(o.value("schema")=="native-migration-status/v1"&&o.value("entries").isArray(),"迁移快照schema/entries无效");QSet<QString> ids;for(auto v:o.value("entries").toArray()){require(v.isObject(),"审查项需对象");auto r=v.toObject();auto id=r.value("id").toString();require(!id.trimmed().isEmpty()&&!ids.contains(id),"审查项身份缺失或重复");ids.insert(id);}return o;}
QString field(const QJsonObject& o,const QString& k){auto v=o.value(k);if(v.isString()&&!v.toString().trimmed().isEmpty())return v.toString();if(v.isBool())return v.toBool()?"是":"否";if(v.isArray()){QStringList values;for(auto x:v.toArray())if(x.isString())values<<x.toString();if(!values.isEmpty())return values.join(" / ");}return "未知";}
static QString dimension(const QJsonObject& o,const QString& k){return field(o,k=="implementation"&&!o.contains(k)?"nativeStatus":k);}
QStringList options(const QJsonObject& o,const QString& key){QSet<QString> values;for(auto v:o.value("entries").toArray())values.insert(dimension(v.toObject(),key));auto result=values.values();result.sort();return result;}
QJsonArray filter(const QJsonObject& o,const QJsonObject& query){validate(o);QJsonArray out;auto search=query.value("search").toString().trimmed();for(auto v:o.value("entries").toArray()){auto r=v.toObject();bool matches=true;for(auto k:{"platform","module","implementation","acceptance","externalBlocker"}){auto wanted=query.value(k).toString();if(!wanted.isEmpty()&&wanted!=dimension(r,k))matches=false;}if(matches&&(search.isEmpty()||QString::fromUtf8(QJsonDocument(r).toJson(QJsonDocument::Compact)).contains(search,Qt::CaseInsensitive)))out.append(r);}return out;}
QString summary(const QJsonObject& o){int partial=0,pending=0,accepted=0,unknown=0;for(auto v:o.value("entries").toArray()){QString s=v.toObject().value("nativeStatus").toString();if(s=="部分实现"||s=="partial")++partial;else if(s=="待迁移"||s=="pending")++pending;else if(s=="fullyAccepted"||s=="完整验收")++accepted;else ++unknown;}return "冻结迁移快照 · 非实时总进度\n版本："+field(o,"version")+" · 时点："+field(o,"asOf")+"\n来源："+field(o,"snapshotSource")+" · 源版本："+field(o,"sourceHead")+"\n注入时间："+field(o,"capturedAt")+" · 陈旧性："+field(o,"stale")+"\n"+QString("%1审查项 · %2部分实现 / %3待迁移 / %4完整验收 / %5未知\n").arg(o.value("entries").toArray().size()).arg(partial).arg(pending).arg(accepted).arg(unknown)+field(o,"scopeNote")+"\n代码、确定性检查、真实来源、人工验收和ARM分别记录；入口存在不代表完成。";}
QStringList references(const QJsonObject& r){QStringList refs;if(r.value("evidenceRefs").isArray()){for(auto v:r.value("evidenceRefs").toArray())if(v.isString()&&!v.toString().trimmed().isEmpty())refs<<v.toString();}else if(r.value("evidence").isString()&&!r.value("evidence").toString().trimmed().isEmpty())refs<<r.value("evidence").toString();return refs;}
QString detail(const QJsonObject& r){QString out=field(r,"id")+" · "+field(r,"title")+"\n平台："+field(r,"platform")+" · 模块："+field(r,"module")+"\n实现："+dimension(r,"implementation")+" · 验收："+field(r,"acceptance")+"\n外部阻断："+field(r,"externalBlocker")+"\n\n完整范围与缺口\n"+field(r,"scope")+"\n\n原验收说明\n"+field(r,"verification")+"\n迁移决策\n"+field(r,"decision")+"\n\n验证维度（缺失为未知）\n";auto dimensions=r.value("verificationDimensions").toObject();for(auto k:{"code","fixture","realSource","manual","arm"})out+=(QString(k)=="code"?"代码存在":QString(k)=="fixture"?"确定性检查":QString(k)=="realSource"?"真实来源":QString(k)=="manual"?"人工验收":"ARM真机")+QString("：")+field(dimensions,k)+"\n";return out+"\n证据引用（由宿主白名单解析）\n"+(references(r).isEmpty()?QString("未知（未提供引用）"):references(r).join("\n"))+"\n\n完整原始审查记录\n"+QString::fromUtf8(QJsonDocument(r).toJson(QJsonDocument::Indented));}
}

